225	    /**
226	     * Builds the customer code for a new owner, formatted {@code '<LAST3>-<NNNN>'} where LAST3 is the
227	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
228	     * sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
229	     *
230	     * @param lastName the owner's last name
231	     * @return the assigned customer code
232	     */
233	    private String nextCustomerCode(String lastName) {
234	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
235	        int sequence = this.clinicService.findAllOwners().size() + 1;
236	        return String.format("%s-%04d", prefix, sequence);
237	    }
238	
239	    /**
240	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
241	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
242	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
243	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
244	     * string is what gets stored and returned.
245	     *
246	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
247	     *
248	     * @param telephone the raw telephone value supplied by the client
249	     * @return the normalized E.164 telephone number
250	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
251	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
252	     *                                 digits after the {@code '+'})
253	     */
254	    private static String normalizeTelephone(String telephone) {
255	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
256	        String digits;
257	        if (cleaned.startsWith("+")) {
258	            digits = cleaned.substring(1);
259	        } else {
260	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
261	            digits = "61" + national;
262	        }
263	        if (!digits.matches("[0-9]{8,15}")) {
264	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
265	                "telephone could not be normalized to a valid E.164 number");
266	        }
267	        return "+" + digits;
268	    }
269	
270	    /**
271	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
272	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
273	     *
274	     * @param telephone the stored telephone value, possibly {@code null}
275	     * @return the E.164 form, or the raw value when it cannot be normalized
276	     */
277	    private static String toComparableTelephone(String telephone) {
278	        try {
279	            return normalizeTelephone(telephone);
280	        } catch (ResponseStatusException ex) {
281	            return telephone;
282	        }
283	    }
284	
285	    /**
286	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
287	     * containing at least one dot, none of the three sections containing whitespace or an
288	     * additional {@code @}.
289	     */
290	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
291	
292	    /**
293	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
294	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
295	     * value is then stored and returned lower-cased.
296	     *
297	     * @param email the raw email value supplied by the client, possibly {@code null}
298	     * @return the lower-cased email, or {@code null} when none was supplied
299	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
300	     *                                 is not a syntactically valid address
301	     */
302	    private static String normalizeEmail(String email) {
303	        if (email == null) {
304	            return null;
305	        }
306	        if (!EMAIL_PATTERN.matcher(email).matches()) {
307	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
308	                "email must be a syntactically valid address");
309	        }
310	        return email.toLowerCase(Locale.ROOT);
311	    }
312	
313	    /**
314	     * Determines whether the given normalized E.164 telephone is already used by any owner other
315	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
316	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
317	     * inputs representing the same number are treated as duplicates.
318	     *
319	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
320	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
321	     * @return {@code true} if another owner already uses the telephone
322	     */
323	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
324	        for (Owner existing : this.clinicService.findAllOwners()) {
325	            if (excludeId != null && excludeId.equals(existing.getId())) {
326	                continue;
327	            }
328	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
329	                return true;
330	            }
331	        }
332	        return false;
333	    }
334	
335	    /**
336	     * Normalizes a value for household comparison: leading/trailing whitespace is trimmed, internal
337	     * runs of whitespace are collapsed to a single space, and the result is lower-cased. This lets
338	     * two last names or addresses that differ only in case or whitespace be treated as equal.
339	     *
340	     * @param value the raw value, possibly {@code null}
341	     * @return the normalized comparison key, or {@code ""} when the value is {@code null}
342	     */
343	    private static String normalizeForHousehold(String value) {
344	        if (value == null) {
345	            return "";
346	        }
347	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
348	    }
349	
350	    /**
351	     * Determines whether another owner (other than {@code excludeId}, or every owner when it is
352	     * {@code null}) already shares the same household, i.e. has the same last name and the same
353	     * address compared case-insensitively with collapsed whitespace.
354	     *
355	     * @param lastName  the last name to check
356	     * @param address   the address to check
357	     * @param excludeId id of an owner to ignore during the check, or {@code null} for none
358	     * @return {@code true} if another owner shares the same last name and address
359	     */
360	    private boolean isHouseholdInUse(String lastName, String address, Integer excludeId) {
361	        String normalizedLastName = normalizeForHousehold(lastName);
362	        String normalizedAddress = normalizeForHousehold(address);
363	        for (Owner existing : this.clinicService.findAllOwners()) {
364	            if (excludeId != null && excludeId.equals(existing.getId())) {
365	                continue;
366	            }
367	            if (normalizedLastName.equals(normalizeForHousehold(existing.getLastName()))
368	                && normalizedAddress.equals(normalizeForHousehold(existing.getAddress()))) {
369	                return true;
370	            }
371	        }
372	        return false;
373	    }
374	}
